solution:
#include <stdio.h>

int main(void) {
    int status, k;
    scanf("%d %d", &status, &k);
    printf("switch %d: %d\n", k, (status >> k) & 1);
    printf("flipped: %d\n", status ^ (1 << k));
    return 0;
}
